import { test, expect } from '@playwright/test';

test.describe('Login Loading Spinner', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000/login');
  });

  test('should display loading spinner while login request is processing', async ({ page }) => {
    // Fill in login credentials
    await page.getByLabel('Email').fill('test@example.com');
    await page.getByLabel('Password').fill('password123');

    // Click login button
    await page.getByRole('button', { name: /login/i }).click();

    // Verify loading spinner is visible
    const spinner = page.getByRole('status', { name: /loading/i });
    await expect(spinner).toBeVisible();
  });

  test('should hide loading spinner after login request completes', async ({ page }) => {
    // Fill in login credentials
    await page.getByLabel('Email').fill('test@example.com');
    await page.getByLabel('Password').fill('password123');

    // Click login button
    await page.getByRole('button', { name: /login/i }).click();

    // Verify loading spinner appears
    const spinner = page.getByRole('status', { name: /loading/i });
    await expect(spinner).toBeVisible();

    // Wait for spinner to disappear after request completes
    await expect(spinner).toBeHidden({ timeout: 10000 });
  });

  test('should disable login button while loading spinner is visible', async ({ page }) => {
    // Fill in login credentials
    await page.getByLabel('Email').fill('test@example.com');
    await page.getByLabel('Password').fill('password123');

    // Click login button
    const loginButton = page.getByRole('button', { name: /login/i });
    await loginButton.click();

    // Verify button is disabled during loading
    await expect(loginButton).toBeDisabled();

    // Wait for button to be enabled again after request completes
    await expect(loginButton).toBeEnabled({ timeout: 10000 });
  });

  test('should display spinner with correct accessibility attributes', async ({ page }) => {
    // Fill in login credentials
    await page.getByLabel('Email').fill('test@example.com');
    await page.getByLabel('Password').fill('password123');

    // Click login button
    await page.getByRole('button', { name: /login/i }).click();

    // Verify spinner has proper accessibility attributes
    const spinner = page.getByRole('status', { name: /loading/i });
    await expect(spinner).toHaveAttribute('aria-live', 'polite');
  });
});
